                    for w2 in range(4):
                        row[idx(d, w2, s)] = row[idx(d, w2, s)] - Wm[w2][w]
                    for s2 in range(2):
                        row[idx(d, w, s2)] = row[idx(d, w, s2)] - Rs[s2][s]
